#pragma once
#ifndef MM_KERNEL_H
#define MM_KERNEL_H
#include "kernel_operator.h"
#include "kernel_common.h"
#include "mm_tiling.h"

template <typename T>
class MMKernel {
public:
    __aicore__ inline void Init(GM_ADDR a, GM_ADDR b, GM_ADDR c, GM_ADDR tm, AscendC::TPipe *p) {
        CopyTiling(&t_, tm);
        aGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(a), t_.M * t_.K);
        bGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(b), t_.K * t_.N);
        cGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(c), t_.M * t_.N);
        if ASCEND_IS_AIV { pipe_ = p; sr_ = t_.blockM / AscendC::GetSubBlockNum(); }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int ci=AscendC::GetBlockIdx()/AscendC::GetSubBlockNum();
            const int si=AscendC::GetSubBlockIdx();
            for(int li=0;li<t_.tasksPerCore;++li){
                const int bx=ci*t_.tasksPerCore+li; if(bx>=BlockCount()) continue;
                for(int r=0;r<sr_;++r){
                    const int ri=bx*t_.blockM+si*sr_+r; if(ri<t_.M) ProcessRow(ri);
                }
            }
        }
    }
private:
    __aicore__ inline int32_t BlockCount() const { return (t_.M + t_.blockM - 1) / t_.blockM; }
    __aicore__ inline void ProcessRow(int32_t row) {
        for (int32_t col = 0; col < t_.N; ++col) {
            float sum = 0.0f;
            for (int32_t k = 0; k < t_.K; ++k) {
                sum += static_cast<float>(aGM_.GetValue(row * t_.K + k)) *
                       static_cast<float>(bGM_.GetValue(k * t_.N + col));
            }
            cGM_.SetValue(row * t_.N + col, static_cast<T>(sum));
        }
    }
private:
    MMKernelTiling t_{}; AscendC::TPipe *pipe_{}; int sr_{};
    AscendC::GlobalTensor<T> aGM_, bGM_, cGM_;
};
#endif

